scratchpad/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/batch20.sql:65:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (126, 93, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Mactaggart et al. (2024) — Adapting and pilot testing a tool to assess the accessibility of primary health facilities for people with disabilities in Luuka District, Uganda (Int J Equity Health)', 'doi:10.1186/s12939-024-02314-0 — PMC11562328, open access; full text persisted this batch as retrieval-log/<session>/18ef7d575e63330c.xml. R9 PRE-CHECKED: DOI not held by any evidence_sources row or staged candidate.', 'RESOLVED', 1, 1, 'NOT ADMITTED THIS BATCH BECAUSE THE ONE NUMBER THAT WOULD PUT IT ON PARAMETER 3 IS IN AN APPENDIX NOT RETRIEVED. The body measures ramp slope and reports failure against a criterion, but the criterion''s value is in Supplementary File Appendix 2 (the full adapted tool). Admitting it with only ''two were too steep'' would file a failure count with no threshold to read it against. tier_guess 1 is a HYPOTHESIS for a Co-1 reading, not a claim: the warrant in the bytes is that eight Ugandan youth researchers with disabilities adapted the instrument over three rounds and co-facilitated the audits; the authors and the analysis are academic (LSHTM / MRC-UVRI). Whether that is co-production in D-0178''s sense or disabled people as trained data collectors is exactly the judgement the next reader must make from the full text, and must not be settled by this guess.', 'WHAT IT SAYS ON RAMPS, VERBATIM FROM THE PERSISTED FULL TEXT: method -- ''For long ramps (over 2 m), 2-3 measurements were taken at various points along the length, and the steepest angle was recorded''; finding -- ''of three facilities with ramps, all reached the minimum required width and had textured, non-slip floors but two were too steep and none had handrails, meaning all failed the overall accessibility criteria for a ramp.'' Five facilities audited, three had ramps. R7: a failure finding. Same cluster as candidates 123/124 (health-facility audits in LMICs) and REF-01006, and the second participatory-audit design found in two batches. NEXT: retrieve Supplementary File Appendix 2 from the publisher (BMC additional files) and read the ramp indicator''s slope criterion.', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', NULL);
scratchpad/session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa/batch20.sql:66:INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (127, 94, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Campillay-Campillay et al. (2022) — Accessibility in People with Disabilities in Primary Healthcare Centers: A Dimension of the Quality of Care (Int J Environ Res Public Health 19:12439)', 'doi:10.3390/ijerph191912439 — PMC9564706, MDPI gold open access. R9 PRE-CHECKED: not held by any evidence_sources row or staged candidate.', 'RESOLVED', 3, 1, 'SCREENED ON ABSTRACT ONLY. An analytical cross-sectional external audit of 18 primary health care centres in the Atacama region, Chile, with a dichotomous compliance guideline across four dimensions (participation, information, accessibility chain, architectural aspects). The abstract reports architectural-aspect compliance averaging 63.9 percent against a 70 percent lower control limit, but DOES NOT SAY whether a ramp-gradient item is among the architectural indicators or what threshold it used. Not admitted until the body is read for that item.', 'Same document type as candidates 123/124 and REF-01006 -- the title-screen false negative batch 19 named. Adds Chile, a jurisdiction the audit cluster lacks. harm_finding=1: the abstract calls the compliance levels ''a critical situation''.', 'session_2026-09-25-research-batch-20-audit-cluster-templer-fhwa', '2026-09-25 04:28', NULL);
