import sqlite3
a=sqlite3.connect('file:$SP/branch.db?mode=ro',uri=True)
b=sqlite3.connect('file:$SP/rebuilt.db?mode=ro',uri=True)
m=sqlite3.connect('file:$SP/main.db?mode=ro',uri=True)
ta={t for (t,) in a.execute("select name from sqlite_master where type='table'")}
tb={t for (t,) in b.execute("select name from sqlite_master where type='table'")}
print('tables only in branch',ta-tb,'only in rebuilt',tb-ta)
print('uv',a.execute('pragma user_version').fetchone(),b.execute('pragma user_version').fetchone())
for t in sorted(ta&tb):
    ca=[c[1] for c in a.execute(f'pragma table_info("{t}")')]
    cb=[c[1] for c in b.execute(f'pragma table_info("{t}")')]
    if ca!=cb: print('COLDIFF',t); continue
    ra=set(a.execute(f'select * from "{t}"').fetchall()); rb=set(b.execute(f'select * from "{t}"').fetchall())
    if ra!=rb:
        print(f'DIFF {t}: branch-only {len(ra-rb)} rebuilt-only {len(rb-ra)}')
        for r in list(ra-rb)[:3]: print('   B:',str(r)[:300])
        for r in list(rb-ra)[:3]: print('   R:',str(r)[:300])
PY

